import { setAccountContext } from './account-context.js';
const roleName={owner:'拥有者',editor:'可编辑',viewer:'只读'};
export function createAccountUI({esc,icon,render,toast,modal,closeModal,confirmDialog,onReady,onExit}){
 let data=null,workspace=null,mode='login',error='',loading=true,admin=null,members=[],busy=false;
 const inviteFromHash=()=>new URLSearchParams(location.hash.split('?')[1]||'').get('invite')||'';
 async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},credentials:'same-origin',...(body?{body:JSON.stringify(body)}:{})});let result;try{result=await response.json();}catch{throw new Error('服务未正确返回，请刷新后重试');}if(!response.ok)throw new Error(result.error||'操作失败');return result;}
 const activeKey=()=>`zhicuo.active-space.${data.user.id}`;
 async function adopt(result){data=result;loading=false;error='';if(data.authenticated){let active;try{active=sessionStorage.getItem(activeKey());}catch{}workspace=data.workspaces.find(w=>w.id===active)||data.workspaces.find(w=>w.personal);if(!workspace)throw new Error('账号未创建学习空间，请联系管理员');setAccountContext({user:data.user,workspace});await onReady({user:data.user,workspace,legacyImportAllowed:data.legacyImportAllowed});}render();}
 async function start(){try{await adopt(await api('/api/auth/me'));}catch(e){loading=false;error=e.message;render();}}
 function authPage(){
  const title=mode==='register'?'创建你的学习账号':mode==='reset'?'重置账号密码':'欢迎回到知错';
  return `<div class="auth-shell"><section class="auth-intro"><a class="auth-brand" href="/">知错<span>.</span></a><div><span class="eyebrow">EVERY MISTAKE, A STEP FORWARD</span><h1>你的错题，<br>在每个设备上<br>接着学。</h1><p>拍照归档、结构化复盘、间隔复习。<br>一个账号，连接自己的积累与共同学习的空间。</p></div><small>个人数据按账号保存 · 共享权限由空间拥有者管理</small></section><section class="auth-panel"><div class="card"><span class="eyebrow">YOUR STUDY ACCOUNT</span><h2>${loading?'正在检查登录状态…':title}</h2>${error?`<p class="account-error" role="alert">${esc(error)}</p>`:''}${loading?'':`<form id="account-auth-form"><input type="hidden" name="mode" value="${mode}">${mode==='reset'?'<label class="field">管理员提供的重置码<input name="token" required maxlength="100" autocomplete="off"></label>':`<label class="field">用户名<input name="username" required minlength="3" maxlength="40" autocomplete="username" pattern="[A-Za-z0-9][A-Za-z0-9_.\\-]{2,39}" placeholder="3–40 位字母、数字、点、下划线或短横线"></label>`}${mode==='register'?'<label class="field">显示名称<input name="displayName" required maxlength="60" autocomplete="nickname" placeholder="学习时如何称呼你"></label>':''}<label class="field">${mode==='reset'?'新密码':'密码'}<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="至少 10 个字符"></label>${mode!=='login'?'<label class="field">确认密码<input name="confirmPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label>':''}<button class="btn primary auth-submit" type="submit">${mode==='register'?'注册并进入工作台':mode==='reset'?'更新密码':'登录工作台'} ${icon('arrow')}</button></form><div class="auth-links"><button class="text-btn" data-account="mode" data-mode="${mode==='login'?'register':'login'}">${mode==='login'?(data?.registrationOpen===false?'注册已关闭':'还没有账号？注册'):'已有账号？返回登录'}</button><button class="text-btn" data-account="mode" data-mode="reset">忘记密码</button></div>${data?.chatgptAvailable?`<div class="auth-divider">或使用已连接的账号</div><button class="btn auth-submit" data-account="site-login">使用 ChatGPT 账号进入</button><a class="text-btn auth-native-link" href="/signin-with-chatgpt" target="_top">前往 ChatGPT 登录</a>`:''}<p class="subtle account-note">密码重置码由管理员提供。首次注册后拥有独立个人空间；共享空间通过邀请码加入。</p>`}</div>${!loading&&error?'<button class="text-btn" data-account="retry">重新检查连接</button>':''}</section></div>`;
 }
 function page(){
  return `<div class="page-heading"><div><div class="eyebrow">ACCOUNT & SHARED SPACES</div><h1>自己的积累，也能一起进步。</h1><p>同一账号跨设备同步；加入共享空间后，按成员权限共同整理与学习。</p></div><button class="btn" data-account="logout">退出登录</button></div><div class="account-grid"><section class="card"><div class="section-title"><h2>我的账号</h2><span class="pill">${data.user.role==='admin'?'管理员':'学习者'}</span></div><form id="account-profile-form"><label class="field">显示名称<input name="displayName" value="${esc(data.user.displayName)}" maxlength="60" required></label><label class="field">联系邮箱（可选）<input type="email" name="email" maxlength="160" value="${esc(data.user.email)}"></label><button class="btn" type="submit">保存资料</button></form><div class="account-identity"><span>${data.user.chatgptLinked?'已绑定 ChatGPT · 拍照归档进入同一账号':'尚未绑定 ChatGPT'}</span>${data.user.chatgptLinked?'':'<button class="text-btn" data-account="link">绑定当前 ChatGPT</button>'}</div><p class="subtle">${data.user.hasPassword?'已设置登录密码，可在其他设备使用用户名登录。':'当前通过 ChatGPT 登录。设置用户名和密码后，也可以在其他设备直接登录同一账号。'}</p><form id="account-password-form"><label class="field">用户名<input name="username" value="${esc(data.user.username||'')}" required minlength="3" maxlength="40" autocomplete="username"></label>${data.user.hasPassword?'<label class="field">当前密码<input name="currentPassword" type="password" required autocomplete="current-password"></label>':''}<label class="field">新密码<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label class="field">确认新密码<input name="confirmPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="btn" type="submit">${data.user.hasPassword?'更新密码并使旧会话失效':'设置用户名和密码'}</button></form><button class="text-btn danger-text" data-account="logout-all">退出所有密码登录会话</button></section><div><section class="card"><div class="section-title"><h2>我的学习空间</h2><span class="subtle">当前：${esc(workspace.name)}</span></div><div class="account-spaces">${data.workspaces.map(w=>`<button class="account-space ${workspace.id===w.id?'selected':''}" data-account="space" data-id="${esc(w.id)}"><span><strong>${esc(w.name)}</strong><small>${w.personal?'个人空间':roleName[w.role]} · ${w.id===workspace.id?'正在使用':'点击切换'}</small></span>${icon(w.personal?'book':'layers')}</button>`).join('')}</div><form id="account-space-form" class="account-inline"><label class="field">新建共享空间<input name="name" required maxlength="60" placeholder="例如：初二一班 / 家庭共学"></label><button class="btn primary">创建</button></form><form id="account-join-form" class="account-inline"><label class="field">加入共享空间<input name="token" required maxlength="200" value="${esc(inviteFromHash())}" placeholder="粘贴拥有者提供的邀请码或邀请链接"></label><button class="btn">加入</button></form><p class="subtle">个人空间不会因创建共享空间而自动共享。需要共享的题目请在相应空间录入或导入。</p></section>${workspace.personal?'':`<section class="card spaced"><div class="section-title"><h2>当前空间成员</h2><button class="text-btn" data-account="members">刷新成员</button></div>${members.length?members.map(m=>`<div class="account-member"><span>${esc(m.display_name)} <small>${roleName[m.role]}</small></span>${workspace.role==='owner'&&m.role!=='owner'?`<div><button class="text-btn" data-account="member-role" data-id="${esc(m.id)}" data-role="${m.role==='viewer'?'editor':'viewer'}">设为${m.role==='viewer'?'可编辑':'只读'}</button><button class="text-btn danger-text" data-account="member-remove" data-id="${esc(m.id)}">移除</button></div>`:''}</div>`).join(''):'<p class="subtle">点击刷新成员查看名单。</p>'}${workspace.role==='owner'?`<div class="account-invite"><p>创建单次邀请码，有效期 7 天。请将邀请码发给需要加入的人。</p><button class="btn" data-account="invite" data-role="editor">邀请可编辑成员</button><button class="btn" data-account="invite" data-role="viewer">邀请只读成员</button><button class="text-btn" data-account="revoke-invites">撤销未使用邀请</button></div>`:'<button class="btn danger-text" data-account="leave">退出此共享空间</button>'}</section>`}</div></div>`;
 }
 function adminPage(){
  if(data?.user.role!=='admin')return '<section class="card"><h1>需要管理员权限</h1></section>';
  if(!admin){void refreshAdmin();return '<section class="card"><h1>正在读取管理后台…</h1></section>';}
  return `<div class="page-heading"><div><div class="eyebrow">SERVER ADMINISTRATION</div><h1>让每个账号，都有清晰的边界。</h1><p>管理注册、用户状态与登录会话。后台显示运营统计，不直接展示用户错题正文。</p></div><button class="btn" data-account="admin-refresh">刷新后台</button></div><div class="admin-stats">${[['users','用户'],['workspaces','学习空间'],['records','云端错题'],['photos','原图']].map(([key,title])=>`<section class="card"><span>${title}</span><strong>${admin.counts[key]}</strong></section>`).join('')}</div><section class="card"><div class="section-title"><h2>注册管理</h2><button class="btn ${admin.registrationOpen?'':'primary'}" data-account="registration" data-open="${!admin.registrationOpen}">${admin.registrationOpen?'关闭新用户注册':'开启新用户注册'}</button></div><p class="subtle">当前${admin.registrationOpen?'允许':'不允许'}用户名注册。站点外层访问范围仍由 Sites 访问设置控制；生成共享邀请码不会自动授予站点访问权限。</p></section><section class="card spaced"><div class="section-title"><h2>用户管理</h2><span class="subtle">${admin.offset?`从第 ${admin.offset+1} 位起`:'最近注册的用户'}</span></div><div class="account-table-scroll"><table class="account-table"><thead><tr><th>用户</th><th>角色 / 状态</th><th>空间</th><th>操作</th></tr></thead><tbody>${admin.users.map(u=>`<tr><td><strong>${esc(u.displayName)}</strong><small>${esc(u.username||'ChatGPT 登录')}${u.chatgptLinked?' · 已绑定':''}</small></td><td>${u.role==='admin'?'管理员':'学习者'} · ${u.status==='active'?'启用':'停用'}</td><td>${u.spaces}</td><td>${u.id===data.user.id?'<span class="subtle">当前账号</span>':`<div class="account-row-actions"><button class="text-btn" data-account="user-status" data-id="${esc(u.id)}" data-status="${u.status==='active'?'disabled':'active'}">${u.status==='active'?'停用':'启用'}</button><button class="text-btn" data-account="user-role" data-id="${esc(u.id)}" data-role="${u.role==='admin'?'user':'admin'}">${u.role==='admin'?'设为学习者':'设为管理员'}</button><button class="text-btn" data-account="user-reset" data-id="${esc(u.id)}">密码重置码</button><button class="text-btn" data-account="user-revoke" data-id="${esc(u.id)}">撤销会话</button></div>`}</td></tr>`).join('')}</tbody></table></div><div class="account-pagination">${admin.offset?'<button class="btn small" data-account="admin-prev">上一页</button>':''}${admin.nextOffset!==null?'<button class="btn small" data-account="admin-next">下一页</button>':''}</div></section><section class="card spaced"><div class="section-title"><h2>最近操作记录</h2><span class="subtle">最近 50 条 · 不记录密码、原图或邀请码</span></div><div class="account-audit">${admin.audit.map(a=>`<div><span>${esc(a.actor||'系统')} · ${esc(a.action)}</span><small>${esc(a.created_at.replace('T',' ').slice(0,19))} · ${esc(a.target)}</small></div>`).join('')||'<p class="subtle">暂无操作记录</p>'}</div></section>`;
 }
 async function refreshAdmin(offset=admin?.offset||0){try{admin={...await api('/api/admin/overview?offset='+offset),offset};render();}catch(e){toast(e.message,'error');admin={counts:{},users:[],audit:[],nextOffset:null,offset:0};render();}}
 async function refreshMembers(){members=(await api('/api/workspaces/members?id='+encodeURIComponent(workspace.id))).members;render();}
 async function selectSpace(id){if(!data.workspaces.some(w=>w.id===id))throw new Error('无权访问该空间');await onExit();try{sessionStorage.setItem(activeKey(),id);}catch{}location.reload();}
 function showCode(title,result){modal(`<div class="modal-heading"><h2>${title}</h2><p>仅在此处显示，请复制并通过你选择的方式告知对方。</p></div><label class="field">${result.url?'邀请链接':'一次性重置码'}<input readonly value="${esc(result.url||result.token)}" onclick="this.select()"></label><p class="subtle">有效期至 ${esc(result.expiresAt.replace('T',' ').slice(0,19))}（UTC）；使用后失效。</p><div class="modal-footer"><button class="btn primary" data-action="close">完成</button></div>`);}
 async function logout(all=false){await onExit();await api(all?'/api/auth/logout-all':'/api/auth/logout',{});for(const storage of [localStorage,sessionStorage]){const remove=[];for(let i=0;i<storage.length;i++){const key=storage.key(i);if(key?.includes(':'+data.user.id))remove.push(key);}remove.forEach(key=>storage.removeItem(key));}setAccountContext(null);location.reload();}
 document.addEventListener('click',event=>{const el=event.target.closest('[data-account]');if(!el)return;event.preventDefault();if(busy)return;
  const action=el.dataset.account;
  if(action==='mode'){if(el.dataset.mode==='register'&&data?.registrationOpen===false){toast('当前已关闭注册','error');return;}mode=el.dataset.mode;error='';render();return;}
  if(action==='logout'||action==='logout-all'){confirmDialog('退出账号？','退出前会尝试同步，并清除此账号的本机学习缓存。请先确认页面显示“云端已同步”；断网时可先导出备份。',()=>{closeModal();void logout(action==='logout-all').catch(e=>toast(e.message,'error'));},'退出登录');return;}
  const run=async()=>{
   if(action==='retry')return start();
   if(action==='site-login'){try{return await adopt(await api('/api/auth/site-login',{}));}catch(e){error=e.message;render();return;}}
   if(action==='space')return selectSpace(el.dataset.id);
   if(action==='link'){await api('/api/auth/link-chatgpt',{});location.reload();return;}
   if(action==='members')return refreshMembers();
   if(action==='invite')return showCode('共享空间邀请码',await api('/api/workspaces/invite',{workspaceId:workspace.id,role:el.dataset.role}));
   if(action==='revoke-invites'){await api('/api/workspaces/revoke-invites',{workspaceId:workspace.id});toast('未使用的邀请码已全部撤销。');return;}
   if(action==='member-role'||action==='member-remove'){
    const apply=async()=>{await api('/api/workspaces/member',{workspaceId:workspace.id,userId:el.dataset.id,role:el.dataset.role,remove:action==='member-remove'});await refreshMembers();};
    if(action==='member-remove'){confirmDialog('移除此成员？','移除后对方将无法继续读取和修改此共享空间。',()=>{closeModal();void apply().catch(e=>toast(e.message,'error'));},'移除');return;}return apply();
   }
   if(action==='leave'){await api('/api/workspaces/leave',{workspaceId:workspace.id});try{sessionStorage.removeItem(activeKey());}catch{}location.reload();return;}
   if(action==='admin-refresh')return refreshAdmin();if(action==='admin-next')return refreshAdmin(admin.nextOffset);if(action==='admin-prev')return refreshAdmin(Math.max(0,admin.offset-50));
   if(action==='registration'){await api('/api/admin/registration',{open:el.dataset.open==='true'});return refreshAdmin();}
   if(action==='user-reset')return showCode('一次性密码重置码',await api('/api/admin/reset-password',{userId:el.dataset.id}));
   if(action==='user-revoke'){await api('/api/admin/revoke-sessions',{userId:el.dataset.id});toast('该用户的密码登录会话已撤销。');return refreshAdmin();}
   if(action==='user-status'||action==='user-role'){confirmDialog(action==='user-status'?'更新账号状态？':'更新管理权限？','此操作会立即撤销该用户已有的密码登录会话，并记录到后台操作日志。',()=>{closeModal();void api('/api/admin/user',{userId:el.dataset.id,...(action==='user-status'?{status:el.dataset.status}:{role:el.dataset.role})}).then(()=>refreshAdmin()).catch(e=>toast(e.message,'error'));},'确认更新');}
  };busy=true;void run().catch(e=>toast(e.message,'error')).finally(()=>{busy=false;});
 });
 document.addEventListener('submit',event=>{const form=event.target;if(!form.id.startsWith('account-'))return;event.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(form));
  const run=async()=>{
   if(['account-auth-form','account-password-form'].includes(form.id)&&values.confirmPassword!==undefined&&values.password!==values.confirmPassword)throw new Error('两次输入的密码不一致');
   if(form.id==='account-auth-form'){
    if(mode==='reset'){await api('/api/auth/reset-password',values);mode='login';error='密码已更新，请用新密码登录。';render();return;}
    const result=await api('/api/auth/'+(mode==='register'?'register':'login'),values);await adopt(result);return;
   }
   if(form.id==='account-profile-form'){await api('/api/auth/profile',values);data.user.displayName=values.displayName;data.user.email=values.email;render();toast('账号资料已更新。');return;}
   if(form.id==='account-password-form'){await api('/api/auth/password',values);toast('用户名和密码已更新。');location.reload();return;}
   if(form.id==='account-space-form'){const created=await api('/api/workspaces/create',values);data.workspaces=(await api('/api/workspaces')).workspaces;return selectSpace(created.id);}
   if(form.id==='account-join-form'){let token=values.token.trim();if(token.startsWith('http')){try{token=new URLSearchParams(new URL(token).hash.split('?')[1]||'').get('invite')||'';}catch{throw new Error('邀请链接无效');}}const joined=await api('/api/workspaces/join',{token});data.workspaces=(await api('/api/workspaces')).workspaces;return selectSpace(joined.id);}
  };busy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);void run().catch(e=>{if(!data?.authenticated){error=e.message;render();}else toast(e.message,'error');}).finally(()=>{busy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);});
 });
 return {start,authPage,page,adminPage,refreshAdmin,isReady:()=>!loading,isAuthenticated:()=>!!data?.authenticated,isAdmin:()=>data?.user?.role==='admin',isReadonly:()=>workspace?.role==='viewer',selectSpace,get workspaces(){return data?.workspaces||[];},get user(){return data?.user;},get workspace(){return workspace;}};
}
